import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

ln_cpp_decl = r"""
#include <torch/extension.h>
#include <vector>
torch::Tensor layernorm_forward(torch::Tensor x,
                                c10::optional<torch::Tensor> weight,
                                c10::optional<torch::Tensor> bias,
                                std::vector<int64_t> normalized_shape,
                                double eps);
"""

ln_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

namespace {
constexpr int kThreads = 256;
constexpr int kMaxChunks = 256;
// Per-thread register cache: each block keeps its whole chunk in
// registers between the statistics and normalize phases (16 float4 =
// 64 floats per thread covers the full chunk for kMaxChunks-way splits).
constexpr int kCacheVecs = 16;
// Fused single-pass LayerNorm. Phase 1 loads each chunk once into
// registers and accumulates fp64 partial statistics (pair-summed fp32
// widening on the mean path, exact FMA TwoProd split on the sum of
// squares, numerics identical to the previous version). Phase 2: the
// last block of each row (atomic ticket) reduces the row partials and
// publishes the mean hi/lo pair plus rstd, then releases a per-row
// flag. Phase 3: all blocks of the row spin on the flag and normalize
// their register-cached chunk, eliminating the second global read pass
// over X and the separate normalize kernel launch. The per-row chunk
// count is capped on the host by the maximum number of co-resident
// blocks so the spin-wait always makes forward progress (blocks are
// dispatched in blockIdx order, as relied upon by decoupled look-back).
__global__ void layernorm_fused_kernel(
    const float* __restrict__ Xp,
    const float* __restrict__ Wp,
    const float* __restrict__ Bp,
    double* __restrict__ partials,
    float* __restrict__ stats,
    unsigned int* __restrict__ counters,
    float* __restrict__ Yp,
    int64_t row_len,
    int64_t chunk_len,
    int64_t chunks,
    float eps)
{
  using namespace cute;
  const int64_t blk   = blockIdx.x;
  const int64_t row   = blk / chunks;
  const int64_t chunk = blk - row * chunks;
  const int64_t start = chunk * chunk_len;
  const int64_t end   = (start + chunk_len < row_len) ? (start + chunk_len) : row_len;
  const float*  xrow  = Xp + row * row_len;
  float*        yrow  = Yp + row * row_len;
  const bool    vec  = ((row_len & 3) == 0);
  const int64_t nvec = vec ? (row_len >> 2) : 0;
  Tensor gX  = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(xrow)), make_shape(nvec));
  Tensor gY  = make_tensor(make_gmem_ptr(reinterpret_cast<float4*>(yrow)),       make_shape(nvec));
  Tensor gW  = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(Wp)),   make_shape(nvec));
  Tensor gB  = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(Bp)),   make_shape(nvec));
  Tensor gXs = make_tensor(make_gmem_ptr(xrow), make_shape(row_len));
  Tensor gYs = make_tensor(make_gmem_ptr(yrow), make_shape(row_len));
  Tensor gWs = make_tensor(make_gmem_ptr(Wp),   make_shape(row_len));
  Tensor gBs = make_tensor(make_gmem_ptr(Bp),   make_shape(row_len));
  const int tid  = threadIdx.x;
  const int lane = tid & 31;
  const int wid  = tid >> 5;
  double s0 = 0.0, q0 = 0.0;
  float er0 = 0.0f;
  float4 vcache[kCacheVecs];
  if (vec) {
    const int64_t v0 = start >> 2;
    const int64_t v1 = end >> 2;
    #pragma unroll
    for (int k = 0; k < kCacheVecs; ++k) {
      const int64_t i = v0 + tid + (int64_t)k * kThreads;
      float4 v = make_float4(0.f, 0.f, 0.f, 0.f);
      if (i < v1) {
        v = gX(i);
        const float s2a = v.x + v.y;
        const float s2b = v.z + v.w;
        s0 += (double)s2a + (double)s2b;
        const float px = v.x * v.x;
        const float py = v.y * v.y;
        const float pz = v.z * v.z;
        const float pw = v.w * v.w;
        q0 += (double)px + (double)py + (double)pz + (double)pw;
        er0 += fmaf(v.x, v.x, -px);
        er0 += fmaf(v.y, v.y, -py);
        er0 += fmaf(v.z, v.z, -pz);
        er0 += fmaf(v.w, v.w, -pw);
      }
      vcache[k] = v;
    }
    // Overflow (very long rows with a residency-capped chunk count):
    // accumulate without caching; re-read from global in phase 3.
    for (int64_t i = v0 + tid + (int64_t)kCacheVecs * kThreads; i < v1; i += kThreads) {
      float4 v = gX(i);
      const float s2a = v.x + v.y;
      const float s2b = v.z + v.w;
      s0 += (double)s2a + (double)s2b;
      const float px = v.x * v.x;
      const float py = v.y * v.y;
      const float pz = v.z * v.z;
      const float pw = v.w * v.w;
      q0 += (double)px + (double)py + (double)pz + (double)pw;
      er0 += fmaf(v.x, v.x, -px);
      er0 += fmaf(v.y, v.y, -py);
      er0 += fmaf(v.z, v.z, -pz);
      er0 += fmaf(v.w, v.w, -pw);
    }
  } else {
    for (int64_t j = start + tid; j < end; j += kThreads) {
      double v = (double)gXs(j);
      s0 += v;
      q0 += v * v;
    }
  }
  // Prefetch the normalize-phase global traffic (weight, bias, and any
  // uncached X overflow) into L2 before entering the ticket/spin phase,
  // so the fetch latency overlaps the wait on the row flag instead of
  // sitting on the critical path of the normalize phase after it.
  if (vec) {
    const int64_t v0 = start >> 2;
    const int64_t v1 = end >> 2;
    const char* xb = reinterpret_cast<const char*>(xrow);
    const char* wb = reinterpret_cast<const char*>(Wp);
    const char* bb = reinterpret_cast<const char*>(Bp);
    const int64_t xover = v0 + (int64_t)kCacheVecs * kThreads;
    // One prefetch per 128B line (8 float4); the chunk base is 16B
    // aligned, and stepping by one line from an interior start still
    // touches every cache line intersecting the chunk.
    for (int64_t i = v0 + (int64_t)tid * 8; i < v1; i += (int64_t)kThreads * 8) {
      if (Wp != nullptr) {
        asm volatile("prefetch.global.L2 [%0];" :: "l"(wb + (i << 4)));
      }
      if (Bp != nullptr) {
        asm volatile("prefetch.global.L2 [%0];" :: "l"(bb + (i << 4)));
      }
      if (i >= xover) {
        asm volatile("prefetch.global.L2 [%0];" :: "l"(xb + (i << 4)));
      }
    }
  }
  __shared__ double sh_sum[kThreads / 32];
  __shared__ double sh_sqs[kThreads / 32];
  q0 += (double)er0;
  double sum = s0;
  double sqs = q0;
  #pragma unroll
  for (int off = 16; off > 0; off >>= 1) {
    sum += __shfl_down_sync(0xffffffffu, sum, off);
    sqs += __shfl_down_sync(0xffffffffu, sqs, off);
  }
  if (lane == 0) {
    sh_sum[wid] = sum;
    sh_sqs[wid] = sqs;
  }
  __syncthreads();
  if (wid == 0) {
    constexpr int NW = kThreads / 32;
    sum = (lane < NW) ? sh_sum[lane] : 0.0;
    sqs = (lane < NW) ? sh_sqs[lane] : 0.0;
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
      sum += __shfl_down_sync(0xffffffffu, sum, off);
      sqs += __shfl_down_sync(0xffffffffu, sqs, off);
    }
    if (lane == 0) {
      double* out = partials + (row * chunks + chunk) * 2;
      out[0] = sum;
      out[1] = sqs;
    }
  }
  __shared__ unsigned int sh_ticket;
  __threadfence();
  __syncthreads();
  if (tid == 0) {
    sh_ticket = atomicAdd(counters + row, 1u);
  }
  __syncthreads();
  if (sh_ticket == (unsigned int)(chunks - 1)) {
    double fsum = 0.0;
    double fsqs = 0.0;
    for (int64_t c = tid; c < chunks; c += kThreads) {
      const double* p = partials + (row * chunks + c) * 2;
      fsum += p[0];
      fsqs += p[1];
    }
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
      fsum += __shfl_down_sync(0xffffffffu, fsum, off);
      fsqs += __shfl_down_sync(0xffffffffu, fsqs, off);
    }
    if (lane == 0) {
      sh_sum[wid] = fsum;
      sh_sqs[wid] = fsqs;
    }
    __syncthreads();
    if (wid == 0) {
      constexpr int NW = kThreads / 32;
      fsum = (lane < NW) ? sh_sum[lane] : 0.0;
      fsqs = (lane < NW) ? sh_sqs[lane] : 0.0;
      #pragma unroll
      for (int off = 16; off > 0; off >>= 1) {
        fsum += __shfl_down_sync(0xffffffffu, fsum, off);
        fsqs += __shfl_down_sync(0xffffffffu, fsqs, off);
      }
      if (lane == 0) {
        double inv_n = 1.0 / (double)row_len;
        double mean  = fsum * inv_n;
        double var   = fsqs * inv_n - mean * mean;
        var = var > 0.0 ? var : 0.0;
        const float mhi = (float)mean;
        const float mlo = (float)(mean - (double)mhi);
        float* out = stats + row * 3;
        out[0] = mhi;
        out[1] = mlo;
        out[2] = (float)rsqrt(var + (double)eps);
      }
    }
    // Release: make the stats stores visible device-wide, then raise
    // the row flag above `chunks`.
    __threadfence();
    __syncthreads();
    if (tid == 0) {
      atomicAdd(counters + row, 1u);
    }
  }
  // Phase 3: spin on the row flag (one thread per block), then
  // normalize the register-cached chunk. Stats are read through the
  // L2-coherent path so no stale L1 line can be observed.
  if (tid == 0) {
    // Poll the row flag with plain L2 loads plus exponential backoff
    // instead of an atomic read-modify-write: with thousands of
    // co-resident blocks all issuing atomicAdd on a handful of
    // counter cache lines, the atomic serialization starves the
    // producer block's release store and the normalize-phase traffic.
    unsigned int ns = 32u;
    while (__ldcg(counters + row) <= (unsigned int)chunks) {
#if __CUDA_ARCH__ >= 700
      __nanosleep(ns);
      if (ns < 1024u) { ns <<= 1; }
#endif
    }
  }
  // Acquire: the flag was observed via L2, so fence before reading
  // the stats published by the producer block.
  __threadfence();
  __syncthreads();
  const float* st = stats + row * 3;
  const float mhi = __ldcg(st + 0);
  const float mlo = __ldcg(st + 1);
  const float rf  = __ldcg(st + 2);
  auto norm = [&](float v) -> float { return ((v - mhi) - mlo) * rf; };
  if (vec) {
    const int64_t v0 = start >> 2;
    const int64_t v1 = end >> 2;
    #pragma unroll
    for (int k = 0; k < kCacheVecs; ++k) {
      const int64_t i = v0 + tid + (int64_t)k * kThreads;
      if (i < v1) {
        float4 v = vcache[k];
        float4 w = make_float4(1.f, 1.f, 1.f, 1.f);
        float4 b = make_float4(0.f, 0.f, 0.f, 0.f);
        if (Wp != nullptr) w = gW(i);
        if (Bp != nullptr) b = gB(i);
        float4 o;
        o.x = fmaf(norm(v.x), w.x, b.x);
        o.y = fmaf(norm(v.y), w.y, b.y);
        o.z = fmaf(norm(v.z), w.z, b.z);
        o.w = fmaf(norm(v.w), w.w, b.w);
        gY(i) = o;
      }
    }
    for (int64_t i = v0 + tid + (int64_t)kCacheVecs * kThreads; i < v1; i += kThreads) {
      float4 v = gX(i);
      float4 w = make_float4(1.f, 1.f, 1.f, 1.f);
      float4 b = make_float4(0.f, 0.f, 0.f, 0.f);
      if (Wp != nullptr) w = gW(i);
      if (Bp != nullptr) b = gB(i);
      float4 o;
      o.x = fmaf(norm(v.x), w.x, b.x);
      o.y = fmaf(norm(v.y), w.y, b.y);
      o.z = fmaf(norm(v.z), w.z, b.z);
      o.w = fmaf(norm(v.w), w.w, b.w);
      gY(i) = o;
    }
  } else {
    for (int64_t j = start + tid; j < end; j += kThreads) {
      float v = gXs(j);
      float w = (Wp != nullptr) ? (float)gWs(j) : 1.f;
      float b = (Bp != nullptr) ? (float)gBs(j) : 0.f;
      gYs(j) = fmaf(norm(v), w, b);
    }
  }
}
} // namespace
torch::Tensor layernorm_forward(torch::Tensor x,
                                c10::optional<torch::Tensor> weight,
                                c10::optional<torch::Tensor> bias,
                                std::vector<int64_t> normalized_shape,
                                double eps)
{
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(!normalized_shape.empty(), "normalized_shape must be non-empty");
  int64_t row_len = 1;
  for (auto d : normalized_shape) {
    TORCH_CHECK(d > 0, "normalized_shape dims must be positive");
    row_len *= d;
  }
  const int64_t nd = x.dim();
  const int64_t nnd = (int64_t)normalized_shape.size();
  TORCH_CHECK(nd >= nnd, "x must have at least normalized_shape dims");
  for (int64_t k = 0; k < nnd; ++k) {
    TORCH_CHECK(x.size(nd - nnd + k) == normalized_shape[k],
                "x trailing dims must match normalized_shape");
  }
  const int64_t numel = x.numel();
  TORCH_CHECK(numel % row_len == 0, "numel must be divisible by row length");
  const int64_t rows = numel / row_len;
  TORCH_CHECK(rows <= 0x7fffffffLL, "too many rows");
  auto xc = x.contiguous();
  torch::Tensor wc, bc;
  const float* wptr = nullptr;
  const float* bptr = nullptr;
  if (weight.has_value() && weight->defined()) {
    TORCH_CHECK(weight->is_cuda() && weight->scalar_type() == at::kFloat,
                "weight must be CUDA float32");
    TORCH_CHECK(weight->numel() == row_len, "weight numel must equal row length");
    wc = weight->contiguous();
    wptr = wc.data_ptr<float>();
  }
  if (bias.has_value() && bias->defined()) {
    TORCH_CHECK(bias->is_cuda() && bias->scalar_type() == at::kFloat,
                "bias must be CUDA float32");
    TORCH_CHECK(bias->numel() == row_len, "bias numel must equal row length");
    bc = bias->contiguous();
    bptr = bc.data_ptr<float>();
  }
  auto y = torch::empty_like(xc);
  // Cap the per-row chunk count by the maximum number of blocks that can
  // be resident at once so the fused kernel's spin-wait always makes
  // forward progress (blocks are dispatched in blockIdx order).
  static int max_resident_blocks = -1;
  if (max_resident_blocks < 0) {
    int dev = 0;
    cudaGetDevice(&dev);
    int num_sms = 0;
    int per_sm = 0;
    cudaDeviceGetAttribute(&num_sms, cudaDevAttrMultiProcessorCount, dev);
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(
        &per_sm, layernorm_fused_kernel, kThreads, 0);
    max_resident_blocks =
        (num_sms > 0 && per_sm > 0) ? (num_sms * per_sm) : 1;
  }
  const int64_t chunk_cap =
      (max_resident_blocks < kMaxChunks) ? (int64_t)max_resident_blocks
                                         : (int64_t)kMaxChunks;
  // Adaptive chunk sizing: size each chunk to exactly fill the
  // per-thread register cache (kCacheVecs float4 per thread), so the
  // normalize phase never re-reads X from global memory, and use the
  // smallest per-row chunk count that still provides enough blocks to
  // occupy every SM. This shrinks the grid, the partials traffic, and
  // the number of blocks spinning on each row flag.
  const int64_t cache_elems = (int64_t)kCacheVecs * kThreads * 4;
  int64_t chunks = (row_len + cache_elems - 1) / cache_elems;
  const int64_t fill_chunks =
      ((int64_t)max_resident_blocks + rows - 1) / rows;
  if (chunks < fill_chunks) chunks = fill_chunks;
  if (chunks > chunk_cap) chunks = chunk_cap;
  if (chunks < 1) chunks = 1;
  int64_t chunk_len = (row_len + chunks - 1) / chunks;
  chunk_len = ((chunk_len + 3) / 4) * 4;
  if (chunk_len < 4) chunk_len = 4;
  chunks = (row_len + chunk_len - 1) / chunk_len;
  if (chunks < 1) chunks = 1;
  TORCH_CHECK(rows <= 0x7fffffffLL / chunks, "too many layernorm work blocks");
  auto partials = torch::empty({rows * chunks * 2}, xc.options().dtype(at::kDouble));
  auto stats = torch::empty({rows * 3}, xc.options());
  auto counters = torch::empty({rows}, xc.options().dtype(at::kInt));
  dim3 grid((unsigned)(rows * chunks));
  dim3 block(kThreads);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  cudaMemsetAsync(counters.data_ptr<int>(), 0, rows * sizeof(int), stream);
  layernorm_fused_kernel<<<grid, block, 0, stream>>>(
      xc.data_ptr<float>(),
      wptr,
      bptr,
      partials.data_ptr<double>(),
      stats.data_ptr<float>(),
      reinterpret_cast<unsigned int*>(counters.data_ptr<int>()),
      y.data_ptr<float>(),
      row_len,
      chunk_len,
      chunks,
      (float)eps);
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "layernorm kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

layernorm_ext = load_inline(
    name="cute_layernorm_ext",
    cpp_sources=ln_cpp_decl,
    cuda_sources=ln_cuda_src,
    functions=["layernorm_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Layer Normalization implemented with a single custom CUTE/CUDA kernel.
    nn.LayerNorm is kept only as the parameter container (weight/bias/eps),
    so state_dict layout and initialization match the reference model exactly;
    all forward computation runs in the custom kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.ln = nn.LayerNorm(normalized_shape=normalized_shape)
        self._ext = layernorm_ext
        self._normalized_shape = list(self.ln.normalized_shape)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.layernorm_forward(
            x,
            self.ln.weight,
            self.ln.bias,
            self._normalized_shape,
            float(self.ln.eps),
        )

